  ('00000000-0000-4000-8000-0001d10e0027', '00000000-0000-4000-8000-00000000d10e', 39, 6, 'actions speak louder than words'),
  ('00000000-0000-4000-8000-0001d10e0028', '00000000-0000-4000-8000-00000000d10e', 40, 6, 'don''t judge a book by its cover'),
  ('00000000-0000-4000-8000-0001d10e0029', '00000000-0000-4000-8000-00000000d10e', 41, 6, 'practice makes perfect'),
  ('00000000-0000-4000-8000-0001d10e002a', '00000000-0000-4000-8000-00000000d10e', 42, 6, 'don''t cry over spilt milk'),
  ('00000000-0000-4000-8000-0001d10e002b', '00000000-0000-4000-8000-00000000d10e', 43, 6, 'could eat a horse'),
  ('00000000-0000-4000-8000-0001d10e002c', '00000000-0000-4000-8000-00000000d10e', 44, 7, 'in the same boat'),
  ('00000000-0000-4000-8000-0001d10e002d', '00000000-0000-4000-8000-00000000d10e', 45, 7, 'the ball is in your court'),
  ('00000000-0000-4000-8000-0001d10e002e', '00000000-0000-4000-8000-00000000d10e', 46, 7, 'like two peas in a pod'),
  ('00000000-0000-4000-8000-0001d10e002f', '00000000-0000-4000-8000-00000000d10e', 47, 7, 'spill the beans'),
  ('00000000-0000-4000-8000-0001d10e0030', '00000000-0000-4000-8000-00000000d10e', 48, 7, 'bury the hatchet')) as x(id, s, k, u, hw)
join public.words w on w.lang = 'en' and lower(w.headword) = x.hw and w.sense = ''
on conflict (id) do nothing;

-- check
select s.title, count(i.*) as items,
       count(*) filter (where i.literal <> '') as with_literal,
       count(*) filter (where i.equivalent <> '') as with_arabic_saying,
       count(*) filter (where i.translation <> '') as with_translation
from public.study_sets s join public.set_items i on i.set_id = s.id
where s.id in ('00000000-0000-4000-8000-00000000f4a5', '00000000-0000-4000-8000-00000000d10e') group by s.title order by s.title;
